function productModal(id,variantId){selectedProduct=id;const p=DZ.getProduct(id);if(!p||p.enabled===false)return toast('این محصول در دسترس نیست.','error');const options=p.variants.filter(v=>v.enabled!==false);if(!options.length)return toast('این محصول گزینهٔ قابل خرید ندارد.','error');selectedVariant=variantId||options.find(v=>DZ.stockAvailable(p.id,v.id)>0)?.id||options[0].id;const v=options.find(v=>v.id===selectedVariant)||options[0];const available=DZ.stockAvailable(p.id,v.id);openModal(`<div class="product-modal-grid"><div class="product-modal-art">${productMedia(p,{loading:'eager'})}</div><div><p class="kicker">DEZHAWO / ${esc(p.category.toUpperCase())}</p><h2 class="modal-title">${esc(p.title)}</h2><p class="product-description">${esc(p.description)}</p><div style="margin-top:19px"><span class="small">${p.category==='digital'?'مدت اشتراک':'رنگ انتخابی'}: <strong>${esc(v.name)}</strong></span><div class="variant-options">${options.map(o=>`<button class="variant-option ${v.id===o.id?'active':''}" data-action="variant" data-variant="${esc(o.id)}" ${DZ.stockAvailable(p.id,o.id)<=0?'disabled':''}>${p.category!=='digital'?`<span class="color-dot" style="--swatch:${/^#[\da-f]{3,8}$/i.test(o.color)?o.color:'#ddd'}"></span>`:''}${esc(o.name)}</button>`).join('')}</div></div><div class="product-modal-price">${money(DZ.price(p,v))}</div><p class="stock-note">${available>0?(p.category==='digital'?'قابل سفارش · تحویل و فعال‌سازی پس از هماهنگی':'موجود در انبار · '+num(available)+' عدد'):'در حال حاضر ناموجود'}</p><div class="form-actions"><div class="quantity-control"><button data-action="product-minus" aria-label="کم کردن تعداد">${icon('minus')}</button><span id="productQuantity">${num(productQuantity)}</span><button data-action="product-plus" aria-label="زیاد کردن تعداد">${icon('plus')}</button></div><button class="btn btn-dark" data-action="add-cart" ${available<=0?'disabled':''}>افزودن به سبد${icon('bag')}</button></div></div></div>`,'product-modal')}
function renderCart(){const lines=DZ.cartLines(),issues=DZ.cartIssues(),pending=DZ.state.reservation?.status==='payment_pending';$('cartTitleCount').textContent=DZ.cartCount()?num(DZ.cartCount())+' انتخاب':'';$('cartBody').innerHTML=lines.length?lines.map(l=>`<div class="cart-line"><div class="cart-line-art">${productMedia(l.product)}</div><div><h3>${esc(l.product.title)}</h3><p>${esc(l.variant.name)}</p><div class="cart-line-foot"><div class="quantity-control"><button data-action="cart-minus" ${pending?'disabled':''} data-product="${esc(l.product.id)}" data-variant="${esc(l.variant.id)}" aria-label="کم کردن تعداد">${icon('minus')}</button><span>${num(l.quantity)}</span><button data-action="cart-plus" ${pending?'disabled':''} data-product="${esc(l.product.id)}" data-variant="${esc(l.variant.id)}" aria-label="زیاد کردن تعداد">${icon('plus')}</button></div><span class="cart-line-price">${money(l.unitPrice*l.quantity)}</span><button data-action="cart-remove" ${pending?'disabled':''} data-product="${esc(l.product.id)}" data-variant="${esc(l.variant.id)}" aria-label="حذف از سبد">${icon('trash')}</button></div></div></div>`).join(''):`<div class="empty-state">${icon('bag')}<h3>جای انتخاب تو خالی است.</h3><p>یک همراه تازه برای روزمره‌ات پیدا کن.</p><button class="btn btn-dark" data-action="shop">کشف محصولات${icon('arrow')}</button></div>`;if(issues.length){if(!lines.length)$('cartBody').innerHTML='';$('cartBody').insertAdjacentHTML('beforeend',`<div class="demo-note" style="margin-top:16px">بعضی اقلام سبد دیگر قابل خرید نیستند. آن‌ها را حذف کنید.</div>`+issues.filter(line=>!lines.some(l=>l.product.id===line.productId&&l.variant.id===line.variantId)).map(line=>`<div class="cart-line"><div><h3>کالای غیرفعال یا حذف‌شده</h3><p>${num(line.quantity)} عدد</p><button class="btn-text" data-action="cart-remove" data-product="${esc(line.productId)}" data-variant="${esc(line.variantId)}" ${pending?'disabled':''}>حذف از سبد${icon('trash')}</button></div></div>`).join(''));}$('cartBottom').hidden=!DZ.cartCount();$('cartBottom').innerHTML=DZ.cartCount()?`<div class="cart-total"><span>جمع سبد خرید</span><strong>${money(DZ.cartTotal())}</strong></div><button class="btn btn-dark" data-action="checkout" ${issues.length?'disabled':''}>${pending?'ادامهٔ پرداخت سفارش':'ادامهٔ خرید'}${icon('arrow')}</button><p>${pending?'پرداخت این سفارش هنوز باز است؛ برای تغییر سبد باید رزرو پایان یابد یا سفارش لغو شود.':'هزینهٔ ارسال در مرحلهٔ بعد محاسبه می‌شود.'}</p>`:''}
